use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    ensures
        a@ == old(a)@.reverse(),
{
    let mut i: usize = 0;
    let mut j: usize = a.len();

    while i < j
        invariant
            a@.len() == old(a)@.len(),
            i <= j,
            j <= a@.len(),

            // Left part already reversed into place
            forall|k: int|
                0 <= k && k < i as int ==>
                    a@[k] == old(a)@[a@.len() - 1 - k],

            // Right part already reversed into place
            forall|k: int|
                j as int <= k && k < a@.len() as int ==>
                    a@[k] == old(a)@[a@.len() - 1 - k],

            // Middle part unchanged (not yet processed)
            forall|k: int|
                i as int <= k && k < j as int ==>
                    a@[k] == old(a)@[k],
        decreases j - i,
    {
        j -= 1;

        if i >= j {
            break;
        }

        a.swap(i, j);

        i += 1;
    }
}

} // verus!

